from pathlib import Path
import pandas as pd
import numpy as np

def _md(df):
    c=[str(x) for x in df.columns]; out=["| "+" | ".join(c)+" |","| "+" | ".join(["---"]*len(c))+" |"]
    for r in df.astype(object).where(pd.notna(df),"").itertuples(index=False,name=None): out.append("| "+" | ".join(str(x).replace("|","\\|") for x in r)+" |")
    return "\n".join(out)+"\n"
def _w(out,name,df,cap,label):
    df.to_csv(out/f"{name}.csv",index=False); (out/f"{name}.md").write_text(f"# {cap}\n\n"+_md(df),encoding="utf-8"); (out/f"{name}.tex").write_text(df.to_latex(index=False,escape=True,caption=cap,label=label,float_format=lambda x:f"{x:.4g}" if isinstance(x,(float,np.floating)) else str(x)),encoding="utf-8")
def build_tables(root: Path):
    root=Path(root); out=root/"results/final_tables"; out.mkdir(parents=True,exist_ok=True)
    dyn=pd.read_csv(root/"results/processed/dynamics_summary_8B5.csv"); temp=pd.read_csv(root/"results/processed/temperature_field_summary_8B4.csv"); size=pd.read_csv(root/"results/processed/size_scaling_summary_8B3.csv"); syn=pd.read_csv(root/"results/processed/physical_synthesis_8B6.csv").iloc[0]; ptemp=pd.read_csv(root/"results/processed/performance_temperature_8C.csv"); psize=pd.read_csv(root/"results/processed/performance_size_8C.csv"); psyn=pd.read_csv(root/"results/processed/performance_synthesis_8C.csv").iloc[0]; camp=pd.read_csv(root/"results/processed/campaign_consistency_summary_8B2.csv")
    h=pd.DataFrame([["Analysis snapshot",syn.analysis_snapshot],["Campaign comparison records",int(syn.comparison_records)],["Unique physical points",int(syn.unique_physical_points)],["Physical-equivalence PASS",int(syn.pass_count)],["Physical-equivalence INCONCLUSIVE",int(syn.inconclusive_count)],["Physical-equivalence FAIL",int(syn.fail_count)],["Repeated points reproducible",f"{int(syn.campaign_reproducible_points)}/{int(syn.campaign_repeated_points)}"],["Robust size series",f"{int(syn.size_series_robust)}/{int(syn.size_series_total)}"],["Maximum measured speed-up",float(psyn.max_speedup)],["Maximum event compression",float(psyn.max_event_compression_temperature_sweep)],["Overall physical conclusion",syn.overall_physical_conclusion]],columns=["Metric","Value"]); _w(out,"table01_headline_summary",h,"Headline results of the Standard Monte Carlo versus n-fold comparison.","tab:headline_summary")
    t=dyn[["dynamics","record_count","pass_count","inconclusive_count","fail_count","median_abs_ratio_deviation_pct","max_abs_ratio_deviation_pct","dynamics_equivalence_status"]].copy(); t.columns=["Dynamics","Records","PASS","INCONCLUSIVE","FAIL","Median |R_tau-1| (%)","Max |R_tau-1| (%)","Status"]; _w(out,"table02_physical_validation_by_dynamics",t,"Physical-equivalence summary separated by stochastic dynamics.","tab:physical_validation_dynamics")
    t=temp[["dynamics","H","T_min","T_max","pass_count","inconclusive_count","fail_count","inconclusive_T_values","lowest_pass_T","max_abs_ratio_deviation_pct","temperature_robustness_status"]].copy(); t.columns=["Dynamics","H/J","T/J min","T/J max","PASS","INCONCLUSIVE","FAIL","Inconclusive T/J","Lowest PASS T/J","Max |R_tau-1| (%)","Status"]; _w(out,"table03_temperature_field_summary",t,"Robustness of physical equivalence across temperature and magnetic field.","tab:temperature_field")
    t=size[["dynamics","H","L_min","L_max","pass_count","inconclusive_count","fail_count","max_abs_ratio_deviation_pct","ratio_slope_percentage_points_per_L_doubling","delta_log_tau_slope_nfold_minus_standard","size_robustness_status"]].copy(); t.columns=["Dynamics","H/J","L min","L max","PASS","INCONCLUSIVE","FAIL","Max |R_tau-1| (%)","R_tau drift (pp / L doubling)","Delta log(tau) slope","Status"]; _w(out,"table04_size_robustness_summary",t,"Robustness of physical equivalence across lattice size.","tab:size_robustness")
    t=ptemp[["dynamics","H","T_min","T_max","speedup_min","speedup_max","nfold_faster_points","standard_faster_points","performance_regime","crossover_T_loglinear","compression_min","compression_max","event_cost_ratio_median"]].copy(); t.columns=["Dynamics","H/J","T/J min","T/J max","Speed-up min","Speed-up max","n-fold faster points","Standard faster points","Regime","Crossover T/J","Compression min","Compression max","Median event-cost ratio"]; _w(out,"table05_temperature_performance_summary",t,"Performance regimes across temperature.","tab:temperature_performance")
    t=psize[["dynamics","H","L_min","L_max","standard_cpu_scaling_exponent_vs_L","nfold_cpu_scaling_exponent_vs_L","speedup_scaling_exponent_vs_L","speedup_geometric_mean","speedup_at_L_min","speedup_at_L_max","performance_winner_all_L"]].copy(); t.columns=["Dynamics","H/J","L min","L max","alpha Standard","alpha n-fold","beta speed-up","Geometric mean speed-up","Speed-up at L min","Speed-up at L max","Winner across tested L"]; _w(out,"table06_size_performance_summary",t,"Performance scaling with lattice size at T/J=1.5.","tab:size_performance")
    t=camp[["dynamics","H","campaign_count","ratio_min","ratio_max","common_ratio_ci_lo","common_ratio_ci_hi","standard_tau_campaign_span_pct","nfold_tau_campaign_span_pct","campaign_consistency_status"]].copy(); t.columns=["Dynamics","H/J","Campaigns","R_tau min","R_tau max","Common CI low","Common CI high","Standard tau span (%)","n-fold tau span (%)","Status"]; _w(out,"tableS01_campaign_reproducibility",t,"Supplementary internal reproducibility across independent campaigns.","tab:campaign_reproducibility")
